{"edits":[{"new":"#include "sorting.h"

#include <utility>
#include <vector>

void bubble_sort(int* a, size_t n) {
    if (a == nullptr || n < 2) {
        return;
    }
    // Each pass moves the largest remaining element to the end; stop early
    // once a pass makes no swaps, since the array is then already sorted.
    for (size_t end = n; end > 1; --end) {
        bool swapped = false;
        for (size_t i = 1; i < end; ++i) {
            if (a[i - 1] > a[i]) {
                std::swap(a[i - 1], a[i]);
                swapped = true;
            }
        }
        if (!swapped) {
            return;
        }
    }
}

namespace {

// Merges the two sorted runs a[lo, mid) and a[mid, hi) into a single sorted
// run, using buf as scratch space.
void merge_runs(int* a, int* buf, size_t lo, size_t mid, size_t hi) {
    size_t left = lo;
    size_t right = mid;
    size_t out = lo;
    while (left < mid && right < hi) {
        // Take from the left run on ties to keep the sort stable.
        if (a[right] < a[left]) {
            buf[out++] = a[right++];
        } else {
            buf[out++] = a[left++];
        }
    }
    while (left < mid) {
        buf[out++] = a[left++];
    }
    while (right < hi) {
        buf[out++] = a[right++];
    }
    for (size_t i = lo; i < hi; ++i) {
        a[i] = buf[i];
    }
}

void merge_sort_range(int* a, int* buf, size_t lo, size_t hi) {
    if (hi - lo < 2) {
        return;
    }
    const size_t mid = lo + (hi - lo) / 2;
    merge_sort_range(a, buf, lo, mid);
    merge_sort_range(a, buf, mid, hi);
    merge_runs(a, buf, lo, mid, hi);
}

}  // namespace

void merge_sort(int* a, size_t n) {
    if (a == nullptr || n < 2) {
        return;
    }
    std::vector<int> buf(n);
    merge_sort_range(a, buf.data(), 0, n);
}
