{"edits":[{"new":"#include "lcs.h"

#include <algorithm>
#include <vector>

int lcs(const std::string& a, const std::string& b) {
    if (a.empty() || b.empty()) return 0;

    // prev[j] = LCS length of a[0..i-1] and b[0..j-1]; only the previous row
    // is needed, so memory is O(min(|a|, |b|)).
    const std::string& rows = a.size() >= b.size() ? a : b;
    const std::string& cols = a.size() >= b.size() ? b : a;

    std::vector<int> prev(cols.size() + 1, 0);
    std::vector<int> cur(cols.size() + 1, 0);

    for (std::size_t i = 1; i <= rows.size(); ++i) {
        cur[0] = 0;
        for (std::size_t j = 1; j <= cols.size(); ++j) {
            if (rows[i - 1] == cols[j - 1]) {
                cur[j] = prev[j - 1] + 1;
            } else {
                cur[j] = std::max(prev[j], cur[j - 1]);
            }
        }
        std::swap(prev, cur);
    }
    return prev[cols.size()];
}
